  'dsc.ranking': { es: 'Quién se sale de la media', en: 'Who is above average', fr: 'Qui dépasse la moyenne', de: 'Wer über dem Schnitt liegt', it: 'Chi supera la media', pt: 'Quem sai da média' },
  'dsc.ranking.expl': { es: 'Ordenado por exceso sobre la media de la flota ({p} %), no por porcentaje: así no se señala a quien tiene pocas entregas. Mínimo {m} entregas.', en: 'Sorted by excess over the fleet average ({p} %), not by rate, so low-volume drivers are not unfairly flagged. Minimum {m} deliveries.', fr: "Trié par excès sur la moyenne ({p} %), pas par taux. Minimum {m} livraisons.", de: 'Nach Überschuss über den Flottenschnitt ({p} %) sortiert, nicht nach Quote. Mindestens {m} Zustellungen.', it: 'Ordinato per eccesso sulla media ({p} %), non per tasso. Minimo {m} consegne.', pt: 'Ordenado por excesso sobre a média ({p} %), não por taxa. Mínimo {m} entregas.' },
