  'dsc.ret.total': { es: '{n} en el periodo', en: '{n} in the period', fr: '{n} sur la période', de: '{n} im Zeitraum', it: '{n} nel periodo', pt: '{n} no período' },
  'dsc.ret.siesta': { es: 'de los {n} fallos por comercio cerrado caen entre las 14 y las 16 h, el cierre del mediodía. Eso es orden de ruta, no conductor.', en: 'of the {n} business-closed failures fall between 2pm and 4pm, the midday closing. That is route order, not the driver.', fr: "des {n} échecs pour commerce fermé tombent entre 14h et 16h. C'est l'ordre de tournée.", de: 'der {n} Fehlschläge wegen geschlossener Geschäfte fallen zwischen 14 und 16 Uhr. Das ist die Routenreihenfolge.', it: 'dei {n} fallimenti per negozio chiuso cadono tra le 14 e le 16. È ordine di percorso.', pt: 'das {n} falhas por comércio fechado caem entre as 14h e as 16h. É ordem de rota.' },
  'dsc.nota': { es: 'DEMOSTRADO que esto NO es el DSC DPMO de Amazon. En 17 scorecards reales el DSC va de 598 a 1712 DPMO (0,06 %-0,17 % de los paquetes), mientras que esta métrica marca un 8,31 %, es decir 83.100 DPMO: 90 veces más. Si Amazon contase «dejar en el jardín» como defecto de DSC, el DPMO sería de decenas de miles. Lo que ves es un hecho comprobable —dónde se dejó cada paquete, según el propio registro de Cortex— y cuánto se sale cada conductor de lo que haría la media de la flota con sus mismas entregas.', en: 'This is not Amazon’s DPMO: Amazon does not publish which locations it penalises or how much, and we do not invent it. What you see is a verifiable fact — where each parcel was left, per Cortex’s own record — and how far each driver deviates from what the fleet average would do with the same deliveries.', fr: "Ce n'est pas le DPMO d'Amazon : Amazon ne publie pas les lieux pénalisés. Ce sont des faits vérifiables issus de Cortex.", de: 'Das ist nicht Amazons DPMO: Amazon veröffentlicht nicht, welche Orte bestraft werden. Dies sind überprüfbare Fakten aus Cortex.', it: 'Non è il DPMO di Amazon: Amazon non pubblica quali luoghi penalizza. Sono fatti verificabili da Cortex.', pt: 'Não é o DPMO da Amazon: a Amazon não publica que locais penaliza. São factos verificáveis do Cortex.' },
