  'whc.ayuda': { es: 'El total de cada conductor lo da el propio portal: aquí solo se compara con tu límite y se ordena por riesgo.', en: 'Each driver\'s total comes from the portal itself: here it is only compared to your limit and sorted by risk.', fr: 'Le total de chaque chauffeur vient du portail : il est seulement comparé à votre limite et trié par risque.', de: 'Die Gesamtstunden kommen aus dem Portal selbst: hier nur mit deinem Limit verglichen und nach Risiko sortiert.', it: 'Il totale di ogni autista viene dal portale: qui si confronta solo con il tuo limite e si ordina per rischio.', pt: 'O total de cada condutor vem do próprio portal: aqui só se compara com o teu limite e ordena-se por risco.' },
  'whc.kpi.superan': { es: 'Superan el límite', en: 'Over the limit', fr: 'Dépassent la limite', de: 'Über dem Limit', it: 'Superano il limite', pt: 'Acima do limite' },
