  'cal.margen.restante': { es: 'fallos más antes de bajar de tier', en: 'more failures before dropping a tier', fr: 'échecs avant de perdre un tier', de: 'weitere Fehler bis zum Tier-Verlust', it: 'altri errori prima di perdere il tier', pt: 'falhas antes de descer de tier' },
  'cal.margen.pasado': { es: 'fallos por encima del objetivo', en: 'failures over target', fr: 'échecs au-dessus de l\'objectif', de: 'Fehler über dem Ziel', it: 'errori oltre l\'obiettivo', pt: 'falhas acima do objetivo' },
  'cal.margen.explica': { es: 'Llevas {usados} fallos de los {tope} que aguanta la semana para cerrar en {dcr} % de DCR, sobre una previsión de {prev} paquetes.', en: 'You have {usados} failures out of the {tope} the week allows to close at {dcr} % DCR, on a forecast of {prev} packages.', fr: 'Vous avez {usados} échecs sur les {tope} que la semaine tolère pour clôturer à {dcr} % de DCR, sur une prévision de {prev} colis.', de: 'Du hast {usados} von {tope} Fehlern, die die Woche für einen Abschluss bei {dcr} % DCR zulässt, bei einer Prognose von {prev} Paketen.', it: 'Hai {usados} errori sui {tope} che la settimana tollera per chiudere al {dcr} % di DCR, su una previsione di {prev} pacchi.', pt: 'Levas {usados} falhas das {tope} que a semana aguenta para fechar em {dcr} % de DCR, sobre uma previsão de {prev} pacotes.' },
  'cal.hoy': { es: 'Jornada de hoy', en: 'Today\'s shift', fr: 'Journée d\'aujourd\'hui', de: 'Heutige Schicht', it: 'Giornata di oggi', pt: 'Jornada de hoje' },
  'cal.hoy.de': { es: 'entregados de {t} en ruta', en: 'delivered of {t} on route', fr: 'livrés sur {t} en tournée', de: 'zugestellt von {t} auf Tour', it: 'consegnati su {t} in rotta', pt: 'entregues de {t} em rota' },
  'cal.hoy.nota': { es: 'Quedan {v} paquetes en la furgoneta: la jornada no puntúa hasta que cierre.', en: '{v} packages still on the van: today doesn\'t score until it closes.', fr: '{v} colis encore dans le van : la journée ne compte pas tant qu\'elle n\'est pas clôturée.', de: '{v} Pakete noch im Fahrzeug: der Tag zählt erst nach Abschluss.', it: '{v} pacchi ancora sul furgone: la giornata non conta finché non chiude.', pt: 'Faltam {v} pacotes na carrinha: o dia não pontua até fechar.' },
  'cal.hoy.sin': { es: 'Sin jornada abierta ahora mismo.', en: 'No open shift right now.', fr: 'Aucune journée en cours.', de: 'Derzeit keine offene Schicht.', it: 'Nessuna giornata aperta al momento.', pt: 'Sem jornada aberta neste momento.' },
  'cal.impacto.titulo': { es: 'Quién se lleva el margen', en: 'Who\'s eating the margin', fr: 'Qui consomme la marge', de: 'Wer den Spielraum aufbraucht', it: 'Chi consuma il margine', pt: 'Quem consome a margem' },
  'cal.impacto.explica': { es: 'No es el ranking de peores: es cuántos fallos hace cada uno POR ENCIMA de lo que haría la media de la flota con sus mismos paquetes. Así no se castiga a quien lleva zona difícil.', en: 'Not a worst-driver ranking: it\'s how many failures each one makes ABOVE what the fleet average would make with the same packages. That way a hard route isn\'t punished.', fr: 'Ce n\'est pas un classement des pires : c\'est le nombre d\'échecs AU-DESSUS de ce que ferait la moyenne de la flotte avec les mêmes colis. Une zone difficile n\'est donc pas pénalisée.', de: 'Kein Ranking der Schlechtesten: es zeigt die Fehler ÜBER dem, was der Flottendurchschnitt mit denselben Paketen machen würde. So wird ein schweres Gebiet nicht bestraft.', it: 'Non è la classifica dei peggiori: è quanti errori fa ciascuno SOPRA quello che farebbe la media della flotta con gli stessi pacchi. Così una zona difficile non viene punita.', pt: 'Não é o ranking dos piores: é quantas falhas cada um faz ACIMA do que faria a média da frota com os mesmos pacotes. Assim não se penaliza quem leva zona difícil.' },
  'cal.impacto.nadie': { es: 'Nadie se sale de la media. El margen se lo lleva el reparto normal, no una persona.', en: 'Nobody is above average. The margin goes to normal operations, not to one person.', fr: 'Personne ne dépasse la moyenne. La marge vient de l\'exploitation normale, pas d\'une personne.', de: 'Niemand liegt über dem Durchschnitt. Der Spielraum geht an den Normalbetrieb, nicht an eine Person.', it: 'Nessuno è sopra la media. Il margine se lo prende l\'operatività normale, non una persona.', pt: 'Ninguém está acima da média. A margem vai para a operação normal, não para uma pessoa.' },
