  'lib.geo.fail':  { es: 'El mapa no ha sabido decir qué hay ahí. Vuelve a intentarlo más tarde.', en: 'The map could not tell what is there. Try again later.', fr: 'La carte n’a pas su dire ce qu’il y a là. Réessaie plus tard.', de: 'Die Karte konnte nicht sagen, was dort ist. Versuch es später erneut.', it: 'La mappa non ha saputo dire cosa c’è lì. Riprova più tardi.', pt: 'O mapa não soube dizer o que há ali. Tenta mais tarde.' },
  // "No puedo encontrar la dirección" de HOY, en vivo. Distinto de la Libreta:
  // esto son paquetes sueltos del día, mientras la ruta sigue en marcha.
  // Los MISSING, en su pestaña. Otro problema que el de las direcciones: aquí
  // se llama al conductor para que mire la furgoneta.
  // ── DASHBOARD: la operación del día ──────────────────────────────────────
  // La franja de arriba tiene que contestar "¿cómo va el día?". Antes ese sitio
  // lo ocupaba un % de inspecciones limpias calculado sobre TODO el histórico:
  // un número que no se movía nunca y con el que no se podía hacer nada.
  'ops.hoy':            { es: 'La operación de hoy', en: 'Today’s operation', fr: 'L’opération du jour', de: 'Der heutige Betrieb', it: 'L’operazione di oggi', pt: 'A operação de hoje' },
  'ops.of':             { es: 'de', en: 'of', fr: 'sur', de: 'von', it: 'di', pt: 'de' },
  'ops.delivered.sub':  { es: 'paquetes entregados', en: 'packages delivered', fr: 'colis livrés', de: 'Pakete zugestellt', it: 'pacchi consegnati', pt: 'pacotes entregues' },
  'ops.brief.delivered': { es: 'de los paquetes de hoy ya está entregado', en: 'of today’s packages already delivered', fr: 'des colis du jour déjà livrés', de: 'der heutigen Pakete sind schon zugestellt', it: 'dei pacchi di oggi già consegnato', pt: 'dos pacotes de hoje já entregue' },
  // Cuando lo que se enseña no es de hoy, el titular tiene que decirlo: "de
