  // ── Portal Conductor (additional) ─────────────────────────────────────────
  'portal.intro':     { es: 'Estos son <b>tus enlaces</b>. Compártelos con tus conductores: entran, ponen su email y suben las fotos. Cada empresa tiene su propio enlace y los datos <b>no se mezclan</b> entre estaciones ni con otras empresas.', en: 'These are <b>your links</b>. Share them with your drivers: they open it, enter their email and upload photos. Each company has its own link and data <b>does not mix</b> between stations or companies.', fr: 'Ce sont <b>vos liens</b>. Partagez-les avec vos chauffeurs : ils s\'y connectent, entrent leur e-mail et envoient les photos. Chaque entreprise a son propre lien et les données <b>ne se mélangent pas</b>.', de: 'Das sind <b>deine Links</b>. Teile sie mit deinen Fahrern: Sie öffnen den Link, geben ihre E-Mail ein und laden Fotos hoch. Jedes Unternehmen hat seinen eigenen Link.', it: 'Questi sono <b>i tuoi link</b>. Condividili con i tuoi autisti: accedono, inseriscono la loro email e caricano le foto. Ogni azienda ha il proprio link e i dati <b>non si mescolano</b>.', pt: 'Estes são <b>os teus links</b>. Partilha-os com os teus motoristas: acedem, colocam o email e enviam as fotos. Cada empresa tem o seu link e os dados <b>não se misturam</b>.' },
  'portal.station.desc': { es: 'Deja el centro ya elegido. El conductor solo pone su email: más rápido y a prueba de errores.', en: 'Leaves the centre pre-selected. The driver just enters their email: faster and error-proof.', fr: 'Laisse le centre déjà sélectionné. Le chauffeur saisit juste son e-mail : plus rapide et sans erreur.', de: 'Lässt das Zentrum vorausgewählt. Der Fahrer gibt nur seine E-Mail ein: schneller und fehlersicher.', it: 'Lascia il centro già selezionato. L\'autista inserisce solo la sua email: più veloce e a prova di errore.', pt: 'Deixa o centro já selecionado. O motorista só coloca o email: mais rápido e sem erros.' },
  'portal.how.1':     { es: 'El conductor abre <b>tu enlace</b> en el móvil.', en: 'The driver opens <b>your link</b> on their phone.', fr: 'Le chauffeur ouvre <b>votre lien</b> sur son mobile.', de: 'Der Fahrer öffnet <b>deinen Link</b> auf dem Handy.', it: 'L\'autista apre <b>il tuo link</b> sul cellulare.', pt: 'O motorista abre <b>o teu link</b> no telemóvel.' },
  'portal.how.2':     { es: 'Elige su nombre/email (los que tú has dado de alta en <b>Conductores</b>).', en: 'Selects their name/email (those you registered in <b>Drivers</b>).', fr: 'Choisit son nom/e-mail (ceux que vous avez enregistrés dans <b>Conducteurs</b>).', de: 'Wählt seinen Namen/E-Mail (die du in <b>Fahrer</b> registriert hast).', it: 'Sceglie il suo nome/email (quelli che hai registrato in <b>Autisti</b>).', pt: 'Escolhe o seu nome/email (os que registaste em <b>Motoristas</b>).' },
  'portal.how.3':     { es: 'Sube las fotos de la furgo. La IA analiza y guarda el peritaje.', en: 'Uploads the van photos. The AI analyses and saves the assessment.', fr: 'Envoie les photos de la camionnette. L\'IA analyse et sauvegarde le rapport.', de: 'Lädt Fotos des Transporters hoch. Die KI analysiert und speichert das Gutachten.', it: 'Carica le foto del furgone. L\'IA analizza e salva la perizia.', pt: 'Envia as fotos da carrinha. A IA analisa e guarda a peritagem.' },
  'portal.how.4':     { es: 'Tú lo ves todo en <b>Inspecciones</b> y <b>Revisión rápida</b>.', en: 'You see everything in <b>Inspections</b> and <b>Quick check</b>.', fr: 'Vous voyez tout dans <b>Inspections</b> et <b>Vérification rapide</b>.', de: 'Du siehst alles in <b>Inspektionen</b> und <b>Schnellcheck</b>.', it: 'Vedi tutto in <b>Ispezioni</b> e <b>Revisione rapida</b>.', pt: 'Vês tudo em <b>Inspeções</b> e <b>Revisão rápida</b>.' },
  'portal.security':  { es: 'Seguridad: el enlace está atado a tu empresa por un identificador único (slug); aunque otra empresa entrase a tu URL, solo vería tu nombre y conductores — no podría leer ni escribir nada de otra DSP.', en: 'Security: the link is tied to your company by a unique identifier (slug); even if another company accessed your URL, they would only see your name and drivers — they cannot read or write anything from another DSP.', fr: 'Sécurité : le lien est lié à votre entreprise par un identifiant unique (slug) ; même si une autre entreprise accédait à votre URL, elle ne verrait que votre nom et vos chauffeurs.', de: 'Sicherheit: Der Link ist durch eine eindeutige Kennung (Slug) an dein Unternehmen gebunden; selbst wenn ein anderes Unternehmen auf deine URL zugreift, sieht es nur deinen Namen und Fahrer.', it: 'Sicurezza: il link è legato alla tua azienda da un identificatore unico (slug); anche se un\'altra azienda accedesse al tuo URL, vedrebbe solo il tuo nome e autisti.', pt: 'Segurança: o link está ligado à tua empresa por um identificador único (slug); mesmo que outra empresa acedesse ao teu URL, só veria o teu nome e motoristas.' },

  // ── Importaciones (additional) ────────────────────────────────────────────
  'imp.fleet.title':  { es: 'Importar vehículos (flota)', en: 'Import vehicles (fleet)', fr: 'Importer véhicules (flotte)', de: 'Fahrzeuge importieren (Flotte)', it: 'Importa veicoli (flotta)', pt: 'Importar veículos (frota)' },
  'imp.fleet.desc.all': { es: 'Sube un Excel/CSV con tu flota. Se crean/actualizan los vehículos (usa el filtro de centro arriba para asignarlos).', en: 'Upload an Excel/CSV with your fleet. Vehicles are created/updated (use the centre filter above to assign them).', fr: 'Envoyez un Excel/CSV avec votre flotte. Les véhicules sont créés/mis à jour (utilisez le filtre centre ci-dessus pour les assigner).', de: 'Excel/CSV mit deiner Flotte hochladen. Fahrzeuge werden erstellt/aktualisiert (Zentrum-Filter oben verwenden).', it: 'Carica un Excel/CSV con la tua flotta. I veicoli vengono creati/aggiornati (usa il filtro centro sopra per assegnarli).', pt: 'Envia um Excel/CSV com a tua frota. Os veículos são criados/atualizados (usa o filtro de centro acima para os atribuir).' },
  'imp.fleet.desc.center': { es: 'Sube un Excel/CSV con tu flota. Se crean/actualizan los vehículos del centro {center}.', en: 'Upload an Excel/CSV with your fleet. Vehicles for centre {center} are created/updated.', fr: 'Envoyez un Excel/CSV avec votre flotte. Les véhicules du centre {center} sont créés/mis à jour.', de: 'Excel/CSV mit deiner Flotte hochladen. Fahrzeuge für Zentrum {center} werden erstellt/aktualisiert.', it: 'Carica un Excel/CSV con la tua flotta. I veicoli del centro {center} vengono creati/aggiornati.', pt: 'Envia um Excel/CSV com a tua frota. Os veículos do centro {center} são criados/atualizados.' },
  'imp.columns.hint': { es: 'Columnas típicas: matrícula, marca, modelo, VIN, centro, ITV, fin de renting. Se detectan automáticamente.', en: 'Typical columns: plate, brand, model, VIN, centre, MOT, lease end. Auto-detected.', fr: 'Colonnes typiques : immatriculation, marque, modèle, VIN, centre, CT, fin location. Détectées automatiquement.', de: 'Typische Spalten: Kennzeichen, Marke, Modell, VIN, Zentrum, TÜV, Leasing-Ende. Automatisch erkannt.', it: 'Colonne tipiche: targa, marca, modello, VIN, centro, revisione, fine leasing. Rilevate automaticamente.', pt: 'Colunas típicas: matrícula, marca, modelo, VIN, centro, inspeção, fim renting. Detetadas automaticamente.' },


