  'px.sinHistorial':   { es: "El paquete ya estaba en este estado en su primera captura: Cortex no expone el historial previo a que la extensión empezara a verlo. Los estados nuevos desde ahora sí quedarán registrados con su hora.", en: "The package was already in this state at its first capture: Cortex does not expose history prior to the extension seeing it. New states from now on will be recorded with their time.", fr: "Le colis était déjà dans cet état à sa première capture : Cortex n'expose pas l'historique antérieur. Les nouveaux états seront enregistrés avec leur heure.", de: "Das Paket war bei der ersten Erfassung bereits in diesem Zustand: Cortex zeigt keinen früheren Verlauf. Neue Zustände werden ab jetzt mit Uhrzeit erfasst.", it: "Il pacco era già in questo stato alla prima acquisizione: Cortex non espone lo storico precedente. I nuovi stati verranno registrati con l'ora.", pt: "O pacote já estava neste estado na primeira captura: o Cortex não expõe o histórico anterior. Os novos estados ficarão registados com a hora." },
  'px.conecta':        { es: "Conecta Cortex", en: "Connect Cortex", fr: "Connecter Cortex", de: "Cortex verbinden", it: "Collega Cortex", pt: "Ligar o Cortex" },
  'px.setupIntro':     { es: "Instala la extensión de navegador. Lee la API real de Cortex con tu sesión (nunca la pantalla) y envía los datos aquí cada 2 minutos.", en: "Install the browser extension. It reads the real Cortex API with your session (never the screen) and sends the data here every 2 minutes.", fr: "Installez l'extension navigateur. Elle lit la vraie API Cortex avec votre session (jamais l'écran) et envoie les données ici toutes les 2 minutes.", de: "Installiere die Browser-Erweiterung. Sie liest die echte Cortex-API mit deiner Session (nie den Bildschirm) und sendet die Daten alle 2 Minuten hierher.", it: "Installa l'estensione del browser. Legge la vera API di Cortex con la tua sessione (mai lo schermo) e invia i dati qui ogni 2 minuti.", pt: "Instala a extensão do navegador. Lê a API real do Cortex com a tua sessão (nunca o ecrã) e envia os dados para aqui a cada 2 minutos." },
